def update_revisions(self, other, stop_revision=None, overwrite=False):
    """See Branch.update_revisions."""
    other.lock_read()
    try:
        other_last_revno, other_last_revision = other.last_revision_info()
        if stop_revision is None:
            stop_revision = other_last_revision
            if _mod_revision.is_null(stop_revision):
                return
        last_rev = _mod_revision.ensure_null(self.last_revision())
        self.fetch(other, stop_revision)
        if not overwrite:
            heads = self.repository.get_graph().heads([stop_revision, last_rev])
            if heads == set([last_rev]):
                return
            elif heads == set([stop_revision, last_rev]):
                raise errors.DivergedBranches(self, other)
            elif heads != set([stop_revision]):
                raise AssertionError("invalid heads: %r" % heads)
        if other_last_revision == stop_revision:
            self.set_last_revision_info(other_last_revno, other_last_revision)
        else:
            if overwrite:
                self.generate_revision_history(stop_revision)
            else:
                self.generate_revision_history(stop_revision, last_rev=last_rev, other_branch=other)
    finally:
        other.unlock()
